import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"伺服設定","description":"伺服器的特殊設定及特殊機制。","frontmatter":{"title":"伺服設定","description":"伺服器的特殊設定及特殊機制。"},"headers":[],"relativePath":"setting/index.md","filePath":"setting.md"}'),t={name:"setting/index.md"};function o(s,e,n,h,d,u){return l(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="伺服設定" tabindex="-1">伺服設定 <a class="header-anchor" href="#伺服設定" aria-label="Permalink to &quot;伺服設定&quot;">​</a></h1><h2 id="基本設定" tabindex="-1">基本設定 <a class="header-anchor" href="#基本設定" aria-label="Permalink to &quot;基本設定&quot;">​</a></h2><ul><li><font color="red"><b>沒有領地及保護區</b></font><ul><li>東西被偷被破壞可以透過<a href="/discord/">Discord</a>進行<a href="/apply/report/">檢舉回報</a><ul><li>我們會盡快幫你處理，並復原你被破壞、被偷的東西</li></ul></li></ul></li><li>防噴裝、死亡扣除部分經驗 <ul><li>除了<a href="/dungeon/intro/">副本服</a>的<a href="/dungeon/sp_setting/"><b>特殊情況</b></a></li><li>死亡時扣除等級的1/10(最少1等，最多10等) <ul><li>玩家經驗等級在1等以下時不扣除經驗</li><li>被玩家擊殺(PVP)時只扣除1等</li></ul></li></ul></li><li>防爆及防燒 <ul><li>除了<a href="/server/res/">資源服</a></li></ul></li><li>有<a href="/feature/simple/">PVP</a><ul><li>預設為關閉，請自行輸入<code>/pvp</code>開啟/關閉</li><li><a href="/server/res/">資源服</a>強制開啟，無法關閉</li></ul></li><li>只有<a href="/server/res/">資源服</a>可以挖掘<b>地獄</b>的遠古遺骸；會生成魚類、夜魅及終界龍</li></ul><h2 id="各分流特殊設定" tabindex="-1">各分流特殊設定 <a class="header-anchor" href="#各分流特殊設定" aria-label="Permalink to &quot;各分流特殊設定&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">公告(2022/07/07)</p><p>由於現在大廳服仍在施工期間，網站資訊可能無法及時更新，請以實際情況及Discord公告為主</p></div><ul><li><b>大廳服</b>(與其他分流同步背包，生物規則同主伺服；無法破壞或使用地圖上的物件)</li><li><a href="/server/sv/"><b>主伺服</b></a></li><li><a href="/server/mh/"><b>設施服</b></a></li><li><a href="/server/res/"><b>資源服</b></a></li><li><a href="/server/De/"><b>副本服</b></a></li></ul><h2 id="特殊設定" tabindex="-1">特殊設定 <a class="header-anchor" href="#特殊設定" aria-label="Permalink to &quot;特殊設定&quot;">​</a></h2><h3 id="獄髓升級模板複製方式" tabindex="-1">獄髓升級模板複製方式 <a class="header-anchor" href="#獄髓升級模板複製方式" aria-label="Permalink to &quot;獄髓升級模板複製方式&quot;">​</a></h3><ul><li>本伺服<font color="red"><b>有更改獄髓升級模板複製時的合成配方</b></font></li><li>合成方式如下<br><img src="https://i.imgur.com/LrZ2AwQ.png" style="width:70%;"></li></ul><h3 id="拿下講台上的書本" tabindex="-1">拿下講台上的書本 <a class="header-anchor" href="#拿下講台上的書本" aria-label="Permalink to &quot;拿下講台上的書本&quot;">​</a></h3><ul><li>本伺服<font color="red"><b>無法透過講台介面拿下書本</b></font>，要拿下書本請直接拆掉講台</li><li>可以利用告示牌將講台上鎖，使用方式同<a href="/feature/lock/">鎖箱子/門</a><br><img src="https://i.imgur.com/s98Ufu3.png" style="width:50%;"></li></ul>',11)])])}const f=a(t,[["render",o]]);export{b as __pageData,f as default};
